SELECT generico5.anunciante AS datoscopia,   MAX(generico5.vehiculo) AS tempattrvehiculonk16626454430,   MIN(generico5.vehiculo) AS tempattrvehiculonk5366548160,   CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) AS mnfechaok,   SUM(CAST(generico5.numanuncios AS SIGNED)) AS sumnumanunciosok,   CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) AS yrfechaok FROM generico5 WHERE ((generico5.anunciante IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM')) AND (((CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) >= 2) AND (CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) <= 12)) OR (CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) IS NULL)) AND (CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) = 2015) AND (generico5.medio = 'TELEVISION NACIONAL')) GROUP BY generico5.anunciante,   mnfechaok,   yrfechaok;
